const std=@import("std");const H=@import("experimental/hybrid_abiotic.zig");const A=@import("simulation/atmosphere_water.zig");
pub fn main()!void{var rng=std.Random.DefaultPrng.init(198357);const r=rng.random();const out=std.io.getStdOut().writer();for(0..1200)|k|{const state=H.State{.liquid=if(k%4==0)0 else @floatCast(r.float(f64)*100),.vapor=@floatCast(r.float(f64)*10),.soil=r.float(f64),.rain=@floatCast(r.float(f64))};const p=H.Params{.dt=@as(f64,@floatFromInt(1+k%20))*180,.area=std.math.pow(f64,2,@as(f64,@floatFromInt(30+k%11))),.temperature=if(k%5==0)273.15 else if(k%5==1)270 else 300,.saturation=r.float(f64)*20};const result=H.step(state,p).?;var disabled=p;disabled.enabled=false;const old=A.PhaseStep.init(p.dt).phase(state.liquid,state.vapor,p.saturation,p.temperature,state.rain).?;const off=H.step(state,disabled).?;try std.testing.expectEqual(@as(f32,@floatCast(old.liquid)),off.state.liquid);try std.testing.expectEqual(@as(f32,@floatCast(old.vapor)),off.state.vapor);try std.testing.expectEqual(@as(f32,@floatCast(old.rain_rate)),off.state.rain);try std.testing.expectEqual(state.soil,off.state.soil);try std.testing.expect(result.state.soil>=0 and result.state.soil<=1);if(p.temperature<=273.15)try std.testing.expectEqual(state.soil,result.state.soil);if(result.stages[0].liquid>0)try std.testing.expect(result.soil_evap_density==0 and result.exposed_seconds==0);try std.json.stringify(.{.before=state,.params=p,.result=result},.{},out);try out.writeByte('\n');}std.debug.print("1200 independent hybrid cases; disabled bit parity/cold/submerged/capacity gates pass\n",.{});}
